-- Split multi-word phrases into individual words
-- Generated by pattern matching

-- Postposition phrases ending with 'ته'

-- Process phrases ending with 'ته'
-- These will be split into [word] + 'ته'
-- Example: 'ما ته' -> 'ما' + 'ته'
UPDATE word_frequencies
SET pos = 'split_pending'
WHERE pashto_word LIKE '% ته'
  AND pashto_word LIKE '% %'
  AND (pos = 'phrase' OR pos = 'postposition_phrase' OR pos IS NULL OR pos = '' OR pos = 'unknown')
  AND pos != 'circumposition'
  AND LENGTH(pashto_word) - LENGTH(REPLACE(pashto_word, ' ', '')) = 1;

