-- Preposition phrases starting with 'د'

-- Process phrases starting with 'د'
-- These will be split into 'د' + [word]
-- Example: 'د یوسف' -> 'د' + 'یوسف'
UPDATE word_frequencies
SET pos = 'split_pending'
WHERE pashto_word LIKE 'د %'
  AND pashto_word LIKE '% %'
  AND (pos = 'phrase' OR pos IS NULL OR pos = '' OR pos = 'unknown')
  AND pashto_word NOT LIKE 'د%کې'
  AND pashto_word NOT LIKE 'د%دپاره'
  AND pashto_word NOT LIKE 'د%په اړه'
  AND pashto_word NOT LIKE 'د%په بارې کې'
  AND pashto_word NOT LIKE 'د%سربېره'
  AND pashto_word NOT LIKE 'د%سره'
  AND pos != 'circumposition'
  AND LENGTH(pashto_word) - LENGTH(REPLACE(pashto_word, ' ', '')) = 1;

