-- Particle phrases with 'به'

-- Process phrases containing 'به'
-- These will be split into [word] + 'به' or 'به' + [word]
-- Example: 'هغه به' -> 'هغه' + 'به'
UPDATE word_frequencies
SET pos = 'split_pending'
WHERE (pashto_word LIKE '% به' OR pashto_word LIKE 'به %')
  AND pashto_word LIKE '% %'
  AND (pos = 'phrase' OR pos = 'particle_phrase' OR pos IS NULL OR pos = '' OR pos = 'unknown')
  AND pos != 'circumposition'
  AND LENGTH(pashto_word) - LENGTH(REPLACE(pashto_word, ' ', '')) = 1;


